// function validateForm(name, email, age) mein three values do
// Name empty: "Name is required"
// Email mein @ nahi: "Invalid email"
// Age < 18: "Must be 18+"
// Sab valid: "Form is valid"

solution:
function validateForm(name, email, age) {
  if (!name) return "Name is required"
  if (!email.includes("@")) return "Invalid email"
  if (age < 18) return "Must be 18+"
  return "Form is valid"
}
